-- =====================================================================
-- JEU DE DÉMONSTRATION FICTIF (pour captures d'écran du mémoire)
-- À exécuter sur une base VIDE créée par « alembic upgrade head ».
-- Toutes les données sont inventées : applications de test, équipes, comptes, problèmes
-- (ceux de problemes_a_saisir.csv et de verite_terrain.csv), diagnostics et solutions « jeu-demo-fictif ».
-- Aucun score de fiabilité (evaluation_fiabilite) ni modèle (modele_fiabilite) n'est inséré.
-- Mot de passe de TOUS les comptes : Demo-Memoire-2026
-- =====================================================================
SET client_encoding = 'UTF8';
BEGIN;
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM utilisateur) THEN
    RAISE EXCEPTION 'La base contient déjà des utilisateurs : utilisez une base vide (maintenance_demo).';
  END IF;
END $$;
ALTER TABLE session_test DISABLE TRIGGER trg_session_test_demande;   -- numéros et dates fournis par le script















SELECT v.nom, v.description, jsonb_build_object('regle', v.regle), 'standard', v.categorie, v.auto, 'regle_statique', 'actif'
FROM (VALUES
('php.syntaxe', 'Erreurs de syntaxe PHP', 'erreur_technique', 'automatisable', 'Le code PHP ne doit pas contenir d''erreur de syntaxe.'),
('php.sql_concat', 'Requêtes SQL non protégées', 'securite', 'partielle', 'Une valeur issue de l''utilisateur ne doit pas être concaténée dans une requête SQL.'),
('php.xss', 'Affichage sans échappement (XSS)', 'securite', 'partielle', 'Une donnée saisie par l''utilisateur ne doit pas être affichée sans échappement.'),
('php.secret_en_dur', 'Secrets écrits en dur', 'securite', 'automatisable', 'Aucun mot de passe, clé d''API ou jeton ne doit être écrit dans le code.'),
('php.fonction_dangereuse', 'Fonctions dangereuses', 'securite', 'partielle', 'Les fonctions comme unserialize, exec ou shell_exec ne doivent pas recevoir de donnée externe.'),
('php.include_dynamique', 'Inclusion dynamique de fichier', 'securite', 'partielle', 'Un fichier inclus ne doit pas être choisi par l''utilisateur.'),
('php.hash_faible', 'Hachage faible des mots de passe', 'securite', 'automatisable', 'Les mots de passe ne doivent pas être hachés avec md5 ou sha1.'),
('php.upload_non_controle', 'Fichier envoyé non contrôlé', 'securite', 'partielle', 'Un fichier envoyé par l''utilisateur doit être contrôlé (type, taille) avant d''être enregistré.'),
('php.variable_non_definie', 'Variable non définie', 'erreur_technique', 'automatisable', 'Une variable ne doit pas être utilisée avant d''être définie.'),
('php.appel_inexistant', 'Appel d''une méthode ou fonction inexistante', 'erreur_technique', 'automatisable', 'Le code ne doit pas appeler une méthode ou une fonction qui n''existe pas.'),
('php.type_incoherent', 'Types incohérents', 'erreur_technique', 'partielle', 'Les types des valeurs échangées entre fonctions doivent être cohérents.'),
('php.division_par_zero', 'Division par zéro', 'erreur_technique', 'partielle', 'Un diviseur doit être vérifié avant la division.'),
('php.code_mort', 'Code mort', 'erreur_technique', 'automatisable', 'Le code inatteignable ou jamais utilisé doit être supprimé.')
) AS v(regle, nom, categorie, auto, description)
WHERE NOT EXISTS (SELECT 1 FROM critere c WHERE c.origine = 'standard' AND c.formulation_structuree->>'regle' = v.regle);
CREATE TEMP TABLE _crit AS SELECT formulation_structuree->>'regle' AS regle, id FROM critere WHERE origine = 'standard';











